//! 🧪️ Actual original typing transfer preserves transaction and mutation backings against the neutral policy fixture.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
use semio_framework_value::{RetainedCloneGrant,retirement::controlled::ControlledRetirement};
use semio_plugin_ownership::original_store_genesis::OriginalStoreBirth;
use semio_plugin_job::original_steps::replied;
fn clock()->Option<u64>{Some(1)}
fn grant()->RetainedCloneGrant{let header=semio_framework_value::RetirementDemand{capacity_bytes:size_of::<OriginalTypingCommit<String>>(),..semio_plugin_job::original_steps::fixed::<OriginalTypingCommit<String>>()};let(quote,_)=semio_framework_job::original_construction_settled_quote::<Box<OriginalTypingCommit<String>>>(semio_plugin_job::original_steps::construction(header),1).unwrap();RetainedCloneGrant{maximum_items:quote.items,maximum_copy_bytes:quote.copy_bytes.max(32768),maximum_capacity_bytes:quote.capacity_bytes.max(1<<20),maximum_release_bytes:1<<20,maximum_depth:quote.depth.max(4096)}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(947),Generation(47),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:4096},clock,u64::MAX,1<<24)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.refreshed_turn_with_decoder(g,decoder,run));let(p,c)=(caller.business_receipt(),caller.construction_receipt());assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes+c.retained_capacity_bytes,p.released_bytes+c.released_bytes));result.unwrap()}
fn retire<T:RetireOwned+Send+'static>(value:T,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let mut owner=ControlledRetirement::retain(value);for step in 0..1000000{if owner.terminal_is_empty(){return}let d=owner.next_demand(32768).unwrap();turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{retired_poll(cx,d,|effect|owner.step(32768,effect))?;Ok(())}));assert!(step<999999)}}
fn owned(window:&SharedUtf8,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->SharedUtf8{let mut cloned=None;for _ in 0..64{turn(caller,decoder,grant(),|cx|{funded(cx,SharedUtf8::lease_demand(),|effect|{let turn=window.admit_clone(effect);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:turn.result.map(|(alias,progress)|{cloned=Some(alias);RetainedCloneStep::Progress(progress)}),work:turn.work})})?;Ok(())});if cloned.is_some(){break}}cloned.expect("funded window clone")}
fn close(source:&mut Option<Box<OriginalTypingCommit<String>>>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for step in 0..1000000{if source.is_none(){return}turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{if source.as_ref().unwrap().terminal_is_empty(){let d=OriginalTypingCommit::<String>::release_demands();retired(cx,d,|_|{drop(source.take());Ok(RetainedCloneStep::Complete(receipt(d)))})?;}else{source.as_mut().unwrap().close_step(cx)?;}Ok(())}));assert!(step<999999)}}
fn finish(mut caller:OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,birth:&mut OriginalStoreBirth){for _ in 0..1000000{if birth.terminal_is_empty(){break}turn(&mut caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|birth.close_step(cx)));}while !decoder.terminal_is_empty(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;decoder.close_on_source(cx)?;Ok(())})));let p=caller.business_receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}caller.retire(grant());}
fn seed(rows:&serde_json::Value)->TypingLedger<String>{let mut ledger=TypingLedger::default();for row in rows.as_array().unwrap(){let leaves=row["leaves"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect();ledger.send(row["window"].as_str().unwrap(),row["tool"].as_str().unwrap(),&protocol::ActorId("fixture".into()),semio_framework_tool_machine::TypingInput::Edit{buffer:row["buffer"].as_str().unwrap().into(),leaves},|_,next|semio_framework_tool_machine::TypingFold::Net(next.to_vec()),protocol::HybridLogicalTimestamp{actor:0,physical_ms:row["deadline"].as_u64().unwrap()-750,logical:0}).unwrap();let original=ledger.open(row["window"].as_str().unwrap()).unwrap();assert_eq!(serde_json::json!(original.states),row["states"]);assert_eq!(original.transaction.tool,original.tool);}ledger}
#[test]
fn original_typing_policy_and_move_only_rows_match_the_neutral_contract(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){
  let mut ledger=seed(&law["rows"]);let mut caller=caller();let mut birth=OriginalStoreBirth::default();let mut decoder=caller.admitted_decoder();let(mut windows,mut tools,mut leaves)=(Vec::new(),Vec::new(),Vec::new());
  let control=case["pass"].as_str()==Some("control");let(raw_suppress,raw_all)=classify_typing_dispatch(case["typing"].as_bool().unwrap(),case["commit"].as_str(),case["view"].as_bool().unwrap());let(suppress,all)=(control&&raw_suppress,!control&&raw_all);let roster_active=control&&case["typing"].as_bool().unwrap()&&(case["commit"].is_null()||raw_suppress);
  for row in law["rows"].as_array().unwrap(){
   let window=row["window"].as_str().unwrap();assert_eq!(ledger.open(window).unwrap().deadline_ms,row["deadline"].as_u64().unwrap());let roster=case["roster"].as_array().unwrap();let present=!roster_active||window.is_empty()||roster.is_empty()||roster.iter().any(|v|v.as_str()==Some(window));
   if original_typing_commit_required(all,suppress&&case["window"].as_str()==Some(window),row["deadline"].as_u64().unwrap(),Some(case["now"].as_u64().unwrap()),!control,Some(present))!=Some(true){continue}
   let original=ledger.open(window).unwrap();let identities:Vec<_>=original.net.iter().map(|m|m.as_ptr()).collect();let backing=original.net.as_ptr();let capacity=original.net.capacity();let tx=original.transaction.id.as_ptr();let key=ledger.resident_key(window).unwrap();let alias=ledger.next_retained_window(None).and_then(|_|{let mut after=None;loop{let next=ledger.next_retained_window(after);match next{Some((name,key))if name.as_str()==window=>break Some((name,key)),Some((name,_))=>after=Some(name.as_str()),None=>break None}}}).unwrap().0;let held=owned(alias,&mut caller,&mut decoder);
   let mut source=None;for denied in [RetainedCloneGrant{maximum_items:0,..grant()},RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_capacity_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()}]{assert!(!turn(&mut caller,&mut decoder,denied,|cx|OriginalTypingCommit::admit(&ledger,alias,key,cx,&mut birth,&mut source)));assert!(source.is_none());let spent=caller.business_receipt();assert!(spent.retained_capacity_bytes==0&&spent.released_bytes==0,"a refused admission allocates nothing and publishes no source");}
   let mut admitted=false;for _ in 0..4096{if turn(&mut caller,&mut decoder,grant(),|cx|OriginalTypingCommit::admit(&ledger,alias,key,cx,&mut birth,&mut source)){admitted=true;break}}assert!(admitted);
   let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,grant(),|cx|{assert!(source.as_mut().unwrap().advance(&mut ledger,&held,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
   for step in 0..1000000{if source.as_ref().unwrap().ready(){break}assert!(!turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..grant()},|cx|source.as_mut().unwrap().advance(&mut ledger,&held,cx)));assert_eq!(caller.business_receipt(),Default::default());turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().advance(&mut ledger,&held,cx));assert!(step<999999)}
   let(mut transaction,mut values)=(None,None);assert!(turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().take_into(&ledger,&mut transaction,&mut values,cx)));assert_eq!(transaction.as_ref().unwrap().id.as_ptr(),tx);assert_eq!(values.as_ref().unwrap().iter().map(|value|value.as_ptr()).collect::<Vec<_>>(),identities);assert_eq!(values.as_ref().unwrap().as_ptr(),backing);assert_eq!(values.as_ref().unwrap().capacity(),capacity);assert!(ledger.open(window).is_none());
   windows.push(window.to_owned());tools.push(transaction.as_ref().unwrap().tool.clone());leaves.push(values.as_ref().unwrap().clone());close(&mut source,&mut caller,&mut decoder);retire(transaction,&mut caller,&mut decoder);retire(values,&mut caller,&mut decoder);retire(held,&mut caller,&mut decoder);
  }
  assert_eq!(serde_json::json!(windows),case["expected"]);assert_eq!(suppress,case["suppress"].as_bool().unwrap());finish(caller,&mut decoder,&mut birth);
 }
}
#[test]
fn original_typing_cancel_keeps_every_accepted_owner_until_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for cut in law["cancelAfter"].as_array().unwrap(){
  let mut ledger=seed(&law["rows"]);let mut caller=caller();let mut birth=OriginalStoreBirth::default();let mut decoder=caller.admitted_decoder();let(window,key)=ledger.next_retained_window(None).unwrap();let held=owned(window,&mut caller,&mut decoder);let mut source=None;for _ in 0..4096{if turn(&mut caller,&mut decoder,grant(),|cx|OriginalTypingCommit::admit(&ledger,window,key,cx,&mut birth,&mut source)){break}}
  for _ in 0..cut.as_u64().unwrap(){if source.as_ref().unwrap().ready(){break}turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().advance(&mut ledger,&held,cx));}
  caller.cancel().cancel_now();close(&mut source,&mut caller,&mut decoder);assert!(source.is_none());retire(held,&mut caller,&mut decoder);finish(caller,&mut decoder,&mut birth);
 }
}

fn close_residents(ledger:&mut TypingLedger<String>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for _ in 0..1048576{if ledger.original_windows_terminal_is_empty(){return}let(mut state,mut key)=(None,None);turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{let d=ledger.original_close_window_demands()?;retired(cx,d,|effect|semio_plugin_ownership::bounded_ownership::plugin_grant_step(effect,|g|{let turn=ledger.close_original_window(&mut state,&mut key,g);RetainedWorkOutcome{result:turn.result.map(RetainedCloneStep::Progress),work:turn.work}}))?;Ok(())}));if state.is_some(){retire(state,caller,decoder)}if key.is_some(){retire(key,caller,decoder)}}panic!("mounted typing residents did not close")}
fn anchor(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->OriginalStoreBirth{let mut birth=OriginalStoreBirth::default();let mut custody=None;let d=semio_plugin_job::original_steps::fixed::<u64>();for _ in 0..4096{let ready=turn(caller,decoder,grant(),|cx|birth.built(cx,&mut custody,semio_plugin_job::original_steps::construction(d),||Ok((Box::new(0u64),semio_plugin_job::original_steps::receipt(d)))));if ready&&custody.take().is_some(){return birth}}panic!("receiving custody anchor must admit")}
fn release(birth:&mut OriginalStoreBirth,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for _ in 0..1000000{if birth.terminal_is_empty(){return}turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|birth.close_step(cx)));}panic!("receiving custody anchor must close")}
#[test]
fn original_typing_reader_survives_funded_growth_and_commits_the_same_net_backing(){
 use semio_plugin_tool_run_operations::OriginalToolLedgerRead;
 use semio_framework_tool_typing_edit::{OriginalTypingEdit,OriginalTypingEditRequest};
 use semio_framework_value::retained_clone::RetainedOwnedProjectionAdmission;
 let shape:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../🔨️modules/🛠️tool-machine/⌨️typing/✍️edit/🧪️tests/🔣️.json")).unwrap();let shape=&shape["resident"];let maximum=shape["maximumTurns"].as_u64().unwrap();let name=shape["readerWindow"].as_str().unwrap();
 let mut ledger=TypingLedger::default();ledger.send(name,"app#type",&protocol::ActorId("reader-author".into()),semio_framework_tool_machine::TypingInput::Edit{buffer:"text".into(),leaves:(0..shape["readerLeaves"].as_u64().unwrap()).map(|i|i.to_string()).collect()},|_,next|semio_framework_tool_machine::TypingFold::Net(next.to_vec()),protocol::HybridLogicalTimestamp{actor:0,physical_ms:10,logical:0}).unwrap();
 let original=ledger.open(name).unwrap();let backing=original.net.as_ptr();let capacity=original.net.capacity();let length=original.net.len();let tx=original.transaction.id.as_ptr();let mut caller=caller();let mut birth=OriginalStoreBirth::default();let mut decoder=caller.admitted_decoder();let mut custody=anchor(&mut caller,&mut decoder);let mut reader=OriginalToolLedgerRead::<TypingState<String>>::default();let(window,key)=ledger.next_retained_window(None).unwrap();assert!(turn(&mut caller,&mut decoder,grant(),|cx|reader.admit(&ledger,window,key,cx)));
 for _ in 0..maximum{if reader.ready(){break}turn(&mut caller,&mut decoder,grant(),|cx|reader.advance(&mut ledger,cx));}assert!(reader.ready());let mut admission=RetainedOwnedProjectionAdmission::<TypingState<String>>::default();let mut projection=None;for _ in 0..maximum{if projection.is_some(){break}turn(&mut caller,&mut decoder,grant(),|cx|{let source=reader.borrow(&ledger)?;if admission.bound_close_available(){let d=admission.take_demand()?;funded(cx,d,|effect|replied(effect,|effect,reply|admission.take(&mut projection,effect,reply).map(drop)))?;}else{let d=admission.demand(source)?;funded(cx,d,|effect|replied(effect,|effect,reply|admission.admit(source,effect,reply).map(drop)))?;}Ok(())});}assert!(projection.is_some());for _ in 0..maximum{if admission.terminal_is_empty(){break}let d=admission.close_demand(grant().maximum_copy_bytes).unwrap();let body=grant().maximum_copy_bytes;turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|{retired_poll(cx,d,|effect|admission.close_step(body,effect))?;Ok(())}));}
 let mut growth=0;let before=format!("a-{:05}",shape["prefixWindows"].as_u64().unwrap()-1);
 for index in 0..shape["prefixWindows"].as_u64().unwrap(){
  let window=format!("a-{index:05}");let mut input=Some(OriginalTypingEditRequest{window:window.clone(),tool:"app#type".into(),actor:protocol::ActorId("prefix-author".into()),buffer:"text".into(),leaves:vec![index.to_string()],clock:protocol::HybridLogicalTimestamp{actor:0,physical_ms:11+index,logical:0}});let mut source=None;let mut admission=semio_framework_job::OriginalConstructionAdmission::default();let mut failure=None;let mut admitted=false;for _ in 0..64{if turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,..grant()},|cx|OriginalTypingEdit::admit(&mut ledger,&mut input,&mut source,&mut admission,&mut failure,cx)){admitted=true;break}}assert!(admitted);
  for _ in 0..maximum{if source.as_ref().unwrap().ready(){break}turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().advance(&mut ledger,cx));let p=caller.business_receipt();if p.retained_capacity_bytes>0&&p.released_bytes>0{growth+=1}assert_eq!(ledger.resident_key(name),Some(key));let value=projection.as_ref().unwrap().borrow().unwrap();let value=value.get();assert_eq!((value.net.as_ptr(),value.net.capacity(),value.net.len()),(backing,capacity,length));}
  assert!(source.as_ref().unwrap().ready());let mut result=None;assert!(turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().take_result(&mut ledger,&mut result,cx)));for _ in 0..maximum{if source.is_none(){break}turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|{if source.as_ref().unwrap().terminal_is_empty(){let d=source.as_ref().unwrap().shell_close_demands();retired(cx,d,|_|{drop(source.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;}else{source.as_mut().unwrap().close_step(&mut ledger,cx)?;}Ok(())}));}assert!(source.is_none());retire(result,&mut caller,&mut decoder);
 }
 assert!(growth>0);assert_eq!(ledger.windows().last(),Some(name));assert!(reader.borrow(&ledger).is_err());
 let(window,current_key)=ledger.next_retained_window(Some(&before)).unwrap();assert_eq!(window.as_str(),name);assert_eq!(current_key,key);let mut commit=None;assert!(!turn(&mut caller,&mut decoder,grant(),|cx|OriginalTypingCommit::admit(&ledger,window,key,cx,&mut birth,&mut commit)));assert!(commit.is_none());
 let projection=projection.as_mut().unwrap();for _ in 0..maximum{if projection.terminal_is_empty(){break}let d=projection.close_demand(grant().maximum_copy_bytes).unwrap();turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|{let body=grant().maximum_copy_bytes;retired_poll(cx,d,|effect|projection.close_step(body,effect))?;Ok(())}));}assert!(projection.terminal_is_empty());for _ in 0..maximum{if reader.terminal_is_empty(){break}turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|reader.close_step(&mut ledger,cx)));}assert!(reader.terminal_is_empty());assert_eq!(ledger.open(name).unwrap().net.as_ptr(),backing);
 let(window,key)=ledger.next_retained_window(Some(&before)).unwrap();let held=owned(window,&mut caller,&mut decoder);assert!(turn(&mut caller,&mut decoder,grant(),|cx|OriginalTypingCommit::admit(&ledger,window,key,cx,&mut birth,&mut commit)));for _ in 0..maximum{if commit.as_ref().unwrap().ready(){break}turn(&mut caller,&mut decoder,grant(),|cx|commit.as_mut().unwrap().advance(&mut ledger,&held,cx));}assert!(commit.as_ref().unwrap().ready());let(mut transaction,mut values)=(None,None);assert!(turn(&mut caller,&mut decoder,grant(),|cx|commit.as_mut().unwrap().take_into(&ledger,&mut transaction,&mut values,cx)));let net=values.as_ref().unwrap();assert_eq!((net.as_ptr(),net.capacity(),net.len()),(backing,capacity,length));assert_eq!(transaction.as_ref().unwrap().id.as_ptr(),tx);assert!(net.iter().enumerate().all(|(index,value)|value==&index.to_string()));assert!(ledger.open(name).is_none());close(&mut commit,&mut caller,&mut decoder);retire(transaction,&mut caller,&mut decoder);retire(values,&mut caller,&mut decoder);retire(held,&mut caller,&mut decoder);close_residents(&mut ledger,&mut caller,&mut decoder);release(&mut custody,&mut caller,&mut decoder);finish(caller,&mut decoder,&mut birth);
}
